//! Optimal 1-late action tables against two-value agreement (exploratory), one per (n, b).
//!
//! Generated by `thesis/supervisor/optimal-adversary/solvers/noise_controller_table.py` from
//! `dp_scaled.py` at commit 82e598e; provenance is in each file's `#` header. Format v1: rows
//! `s u a1_lo a1_hi m o` give the action (m fresh blocks, o re-blocks) for every state with
//! |B_{t−1}| = s, |U_{t−1}| = u and a1 ∈ [a1_lo, a1_hi] servers of U_{t−1} holding the larger
//! value; every state not listed blocks nobody.

use std::sync::OnceLock;

const FORMAT: &str = "noise-controller-table v1";

const SOURCES: [(usize, usize, &str); 6] = [
    (
        30,
        3,
        include_str!("../../../data/noise_controller/n30_b3.txt"),
    ),
    (
        50,
        5,
        include_str!("../../../data/noise_controller/n50_b5.txt"),
    ),
    (
        50,
        7,
        include_str!("../../../data/noise_controller/n50_b7.txt"),
    ),
    (
        100,
        10,
        include_str!("../../../data/noise_controller/n100_b10.txt"),
    ),
    (
        100,
        14,
        include_str!("../../../data/noise_controller/n100_b14.txt"),
    ),
    (
        200,
        20,
        include_str!("../../../data/noise_controller/n200_b20.txt"),
    ),
];

pub(crate) struct ActionTable {
    n: usize,
    b: usize,
    /// Indexed by s * states + u(u+1)/2 + a1.
    actions: Vec<(u16, u16)>,
}

impl ActionTable {
    pub(crate) fn b(&self) -> usize {
        self.b
    }

    /// (m fresh, o re-blocks) for |B_{t−1}| = s and U_{t−1} = (u servers, a1 of the larger value).
    pub(crate) fn action(&self, s: usize, u: usize, a1: usize) -> (usize, usize) {
        assert!(
            s <= self.b && u <= self.n && a1 <= u,
            "state (s={s}, u={u}, a1={a1}) outside the n={}, b={} table",
            self.n,
            self.b
        );
        let (m, o) = self.actions[s * states(self.n) + u * (u + 1) / 2 + a1];
        (m as usize, o as usize)
    }
}

fn states(n: usize) -> usize {
    (n + 1) * (n + 2) / 2
}

fn header_field<'a>(text: &'a str, key: &str) -> Result<&'a str, String> {
    text.lines()
        .filter_map(|line| line.strip_prefix("# "))
        .find_map(|line| line.strip_prefix(key)?.strip_prefix(": "))
        .ok_or_else(|| format!("noise_controller table header lacks `{key}`"))
}

pub(crate) fn parse(text: &str) -> Result<ActionTable, String> {
    if header_field(text, "format")? != FORMAT {
        return Err(format!("noise_controller table is not `{FORMAT}`"));
    }
    let number = |key: &str| -> Result<usize, String> {
        header_field(text, key)?
            .parse()
            .map_err(|e| format!("header `{key}`: {e}"))
    };
    let (n, b) = (number("n")?, number("b")?);
    let mut actions = vec![(0u16, 0u16); (b + 1) * states(n)];
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let fields: Vec<usize> = line
            .split_whitespace()
            .map(|f| f.parse().map_err(|e| format!("row `{line}`: {e}")))
            .collect::<Result<_, _>>()?;
        let [s, u, lo, hi, m, o] = fields[..] else {
            return Err(format!("row `{line}` needs 6 fields"));
        };
        let consistent = s <= b
            && u <= n
            && 1 <= lo
            && lo <= hi
            && hi < u
            && m + o <= b
            && o <= s
            && m <= n - s
            && (m, o) != (0, 0);
        if !consistent {
            return Err(format!("row `{line}` is inconsistent for n={n}, b={b}"));
        }
        for a1 in lo..=hi {
            actions[s * states(n) + u * (u + 1) / 2 + a1] = (m as u16, o as u16);
        }
    }
    Ok(ActionTable { n, b, actions })
}

fn registry() -> &'static [ActionTable] {
    static TABLES: OnceLock<Vec<ActionTable>> = OnceLock::new();
    TABLES.get_or_init(|| {
        SOURCES
            .iter()
            .map(|&(n, b, text)| {
                let table = parse(text).unwrap_or_else(|e| panic!("table n={n}, b={b}: {e}"));
                assert_eq!(
                    (table.n, table.b),
                    (n, b),
                    "table registered under the wrong key"
                );
                table
            })
            .collect()
    })
}

pub(crate) fn tabulated() -> impl Iterator<Item = (usize, usize)> {
    SOURCES.iter().map(|&(n, b, _)| (n, b))
}

pub(crate) fn lookup(n: usize, b: usize) -> Option<&'static ActionTable> {
    registry().iter().find(|t| (t.n, t.b) == (n, b))
}

pub(crate) fn missing_table(n: usize, b: usize) -> String {
    let have: Vec<String> = tabulated().map(|(n, b)| format!("({n}, {b})")).collect();
    format!(
        "no noise_controller table for n={n}, b={b}; tabulated (n, b): {}",
        have.join(", ")
    )
}
